solution_code:
#include <iostream>

class Score {
    int m_value;
public:
    Score(int value = 100)
        : m_value{ value }
    {}

    int getValue() const { return m_value; }
};

int main() {
    int n{};
    std::cin >> n;
    Score s1{};
    Score s2{ n };
    std::cout << "Default: " << s1.getValue() << "\n";
    std::cout << "Provided: " << s2.getValue() << "\n";
}

