#include <iostream>
#include <string>

class Account {
    std::string m_owner;
    int m_balance;
public:
    // TODO: This class needs TWO constructors (lesson 14.11):
    //   1. A default constructor (no parameters) representing an empty
    //      account: owner "none", balance 0.
    //   2. A constructor taking an owner name and a balance.
    // Once you write any constructor the compiler no longer supplies a
    // default one, so you must write the no-argument constructor yourself.

    const std::string& owner() const { return m_owner; }
    int balance() const { return m_balance; }
};

int main() {
    std::string name{};
    int balance{};
    std::cin >> name >> balance;

    Account empty{};
    Account custom{ name, balance };

    std::cout << "Empty account: " << empty.owner() << ", " << empty.balance() << "\n";
    std::cout << "Custom account: " << custom.owner() << ", " << custom.balance() << "\n";
}

solution_code:
#include <iostream>
#include <string>

class Account {
    std::string m_owner;
    int m_balance;
public:
    Account()
        : m_owner{ "none" }, m_balance{ 0 }
    {}

    Account(std::string owner, int balance)
        : m_owner{ owner }, m_balance{ balance }
    {}

    const std::string& owner() const { return m_owner; }
    int balance() const { return m_balance; }
};

int main() {
    std::string name{};
    int balance{};
    std::cin >> name >> balance;

    Account empty{};
    Account custom{ name, balance };

    std::cout << "Empty account: " << empty.owner() << ", " << empty.balance() << "\n";
    std::cout << "Custom account: " << custom.owner() << ", " << custom.balance() << "\n";
}
